<?php $discount=0;if(!empty($item['compare_price'])){$compareMinor=App\Support\Money::minor((string)$item['compare_price']);$priceMinor=App\Support\Money::minor((string)$item['price']);if($compareMinor>$priceMinor&&$compareMinor>0)$discount=(int)floor((($compareMinor-$priceMinor)*100)/$compareMinor);} ?>
<article class="shop-card"><a class="shop-card-media" href="/<?= e($store['slug']) ?>/product/<?= e($item['slug']) ?>"><?php if($item['image']):?><img src="<?= e($item['image']) ?>" alt="<?= e($item['name']) ?>" loading="lazy" width="600" height="600"><?php else:?><span class="product-placeholder" aria-hidden="true"><?= e(mb_strtoupper(mb_substr($item['name'],0,1))) ?></span><?php endif ?><?php if($discount>0):?><span class="discount-chip">−<?= e($discount) ?>%</span><?php endif ?><?php if($item['availability']!=='AVAILABLE'):?><span class="availability-chip">Unavailable</span><?php endif ?></a><div class="shop-card-body"><?php if(!empty($item['category_name'])):?><span class="shop-category"><?= e($item['category_name']) ?></span><?php endif ?><a class="shop-product-name" href="/<?= e($store['slug']) ?>/product/<?= e($item['slug']) ?>"><?= e($item['name']) ?></a><div class="shop-price"><strong><?= e($store['currency_code']) ?> <?= e($item['price']) ?></strong><?php if($item['compare_price']):?><del><?= e($item['compare_price']) ?></del><?php endif ?></div><?php if($item['availability']!=='AVAILABLE'):?><button class="card-add" type="button" disabled>Unavailable</button><?php elseif((int)$item['variant_count']>0):?><a class="card-add choose" href="/<?= e($store['slug']) ?>/product/<?= e($item['slug']) ?>">Choose options</a><?php else:?><button class="card-add" type="button" data-cart-add data-product-id="<?= e($item['id']) ?>" data-name="<?= e($item['name']) ?>" data-price="<?= e($item['price']) ?>" data-image="<?= e($item['image']??'') ?>" data-url="/<?= e($store['slug']) ?>/product/<?= e($item['slug']) ?>">Add to cart</button><?php endif ?></div></article>
